<?php
declare(strict_types=1);
namespace CajeerBook;
final class GitHubView
{
    public static function render(array $db,string $csrf,bool $admin,?array $preview=null,string $notice=''):string{
        $e=Markdown::e(...);$url=$e(WorkspaceUrls::url('/studio/git'));$hidden='<input type="hidden" name="csrf" value="'.$e($csrf).'">';$c=$db['github']??null;$provider=GitHubSync::label($c??[]);$proposal=GitHubSync::proposalLabel($c??[]);
        $html='<h1>Git Sync</h1><p>Import a GitHub or GitLab branch as drafts; publication and review rules remain in force. Synchronize a documentation directory, not an entire application repository.</p>';
        if($notice!=='')$html.='<p role="status" class="notice">'.$e($notice).'</p>';
        if(!$c){if(!$admin)return $html.'<p>Ask an administrator to connect a repository.</p>';
            return $html.'<form method="post" action="'.$url.'" class="editor">'.$hidden.'<label>Provider<select name="provider"><option value="github">GitHub</option><option value="gitlab">GitLab</option></select></label><label>GitLab origin (ignored for GitHub)<input name="origin" value="https://gitlab.com" maxlength="300"></label><label>Repository (namespace/project)<input name="repo" required maxlength="240" placeholder="example/docs"></label><label>Branch<input name="branch" required value="main" maxlength="200"></label><label>Documentation directory (empty for repository root)<input name="root" maxlength="512" placeholder="docs"></label><label>Book slug<input name="book" required maxlength="64" placeholder="guide"></label><label>Version<input name="version" required maxlength="64" value="1.0"></label><label>Access token (optional for public repositories)<input type="password" name="token" autocomplete="new-password" maxlength="512"></label><label><input type="checkbox" name="push" value="1"> Allow editors to send tracked drafts to this repository via Pull / Merge Requests (may disclose private documentation to repository readers)</label><p>Private repositories require a token and server-side BOOK_GITHUB_KEY. GitHub: Contents read; proposals require Contents and Pull requests write. GitLab: read_api for pull, api for proposals. Self-managed GitLab must be enabled by the server operator.</p><button name="action" value="configure">Connect repository</button></form>';
        }
        $rev='<input type="hidden" name="revision" value="'.$c['revision'].'">';$html.='<h2>'.$e($provider.' · '.$c['repo']).'</h2><p>Origin <code>'.$e($c['origin']??'https://github.com').'</code>'.(isset($c['project_id'])?' · Project ID <code>'.$c['project_id'].'</code>':'').' · Branch <code>'.$e($c['branch']).'</code> · Directory <code>'.$e($c['root']?:'/').'</code> · Target <code>'.$e($c['book'].'/'.$c['version']).'</code></p><p>Last synchronized commit: <code>'.$e($c['commit']?:'Not synchronized').'</code> · '.count($c['pages']).' tracked pages · '.($c['credential']!==''?'Token configured':'Public access').'</p>';
        $html.='<form method="post" action="'.$url.'">'.$hidden.'<button name="action" value="preview">Preview sync</button></form>';
        if($preview!==null){$html.='<h2>Sync plan</h2><p>Commit <code>'.$e($preview['commit']).'</code>'.($preview['author']!==''?' · Git author: '.$e($preview['author']):'').' · '.$preview['conflicts'].' conflicts/removals · '.$preview['blocked'].' blocked · '.$preview['ignored'].' unsupported files ignored; '.$preview['downloaded'].' downloaded, '.$preview['cached'].' cached blobs.</p><table><thead><tr><th>Source</th><th>Page</th><th>Status</th></tr></thead><tbody>';
            foreach($preview['rows'] as $row)$html.='<tr><td>'.$e($row['source']).'</td><td>'.$e($row['target']).'</td><td>'.$e($row['state'].(isset($row['from'])?' from '.$row['from']:'' )).'</td></tr>'; $html.='</tbody></table>';
            foreach($preview['diffs'] as $path=>$diff){$html.='<details><summary>Compare local → '.$e($provider).': '.$e($path).'</summary><pre>';foreach($diff as [$type,$text])$html.=$e(($type==='add'?'+ ':($type==='remove'?'- ':'  ')).$text)."\n";$html.='</pre></details>';}
            if($preview['warnings']){$html.='<details><summary>Unresolved links ('.count($preview['warnings']).')</summary><ul>';foreach($preview['warnings'] as $w)$html.='<li>'.$e($w['source'].' → '.$w['url']).'</li>';$html.='</ul></details>';}
            if($preview['blocked'])$html.='<p>Blocked: a tracked page moved, was deleted or changed its source slug. Restore the original path or disconnect and reconnect deliberately. No changes applied.</p>';
            else $html.='<form method="post" action="'.$url.'" class="editor">'.$hidden.'<input type="hidden" name="commit" value="'.$e($preview['commit']).'"><input type="hidden" name="preview_token" value="'.$e($preview['token']).'"><label>Conflicts / removed sources<select name="resolution"><option value="safe">Stop if conflicts or removals exist</option><option value="remote">Use remote for conflicting drafts; retain removed pages locally</option><option value="local">Keep local conflicting drafts; retain removed pages locally</option><option value="manual">Choose per source below</option></select></label>';
            if(!$preview['blocked']){foreach($preview['rows'] as $path=>$r)if(in_array($r['state'],['conflict','removed'],true))$html.='<label>'.$e((string)$path).'<select name="decision['.hash('sha256',(string)$path).']"><option value="">Choose resolution (manual mode)</option>'.($r['state']==='removed'?'<option value="detach">Retain page and detach source</option>':'<option value="local">Keep local draft</option><option value="remote">Use remote draft</option>').'</select></label>';
            $html.='<p>Removed Git files are detached, never deleted or unpublished. Local-only changes are preserved.</p><button name="action" value="apply">Apply sync as drafts</button></form>';}
        }
        if($c['push']&&$c['commit']!==''){$tracked=[];$changes=[];foreach($c['pages'] as $path=>$p){$tracked[$p['key']]=true;$entry=$db['pages'][$p['key']]??null;if(!$entry||GitHubSync::fingerprint($entry['draft'])!==$p['base'])$changes[]=$path;}$new=[];foreach($db['pages'] as $key=>$entry)if(PageTree::scope($key)===$c['book'].'/'.$c['version']&&!isset($tracked[$key]))$new[]=$key;
            $html.='<h2>Propose local changes</h2><p>'.count($changes).' changed tracked source(s); '.count($new).' untracked local page(s).</p><details><summary>Show proposal candidates</summary><ul>';foreach($changes as $path)$html.='<li>Tracked: '.$e($path).'</li>';foreach($new as $key)$html.='<li>Optional new: '.$e($key).'</li>';$html.='</ul></details><p>Modified tracked Markdown is sent by default; new pages in the target book/version require explicit opt-in. Local-only attachments must be added to Git first. A new branch and '.$proposal.' are created; the base branch is never written. This sends drafts to '.$provider.', where repository permissions apply.</p><form method="post" action="'.$url.'">'.$hidden.$rev.'<input type="hidden" name="state" value="'.GitHubSync::stateHash($db).'"><label><input type="checkbox" name="include_new" value="1"> Include untracked local pages listed above</label><label><input type="checkbox" name="confirm" value="1" required> I authorize sending the selected draft content to the configured repository.</label><button name="action" value="propose">Create '.$proposal.'</button></form>';}
        if($admin)$html.='<h2>Connection settings</h2><form method="post" action="'.$url.'" class="editor">'.$hidden.$rev.'<label>Replace token (empty for public read-only)<input type="password" name="token" autocomplete="new-password" maxlength="512"></label><label><input type="checkbox" name="push" value="1"'.($c['push']?' checked':'').'> Allow draft proposals to '.$provider.'</label><button name="action" value="rotate">Replace credentials</button></form><form method="post" action="'.$url.'">'.$hidden.$rev.'<label><input type="checkbox" name="confirm" value="1" required> Disconnect and discard sync baseline (documents remain)</label><button name="action" value="disconnect">Disconnect</button></form>';
        $html.='<h2>Sync history</h2><ul>';foreach(array_reverse($c['runs']) as $r){$detail=$e($r['detail']);if($r['type']==='proposal'&&preg_match('~\A'.preg_quote(($c['origin']??'https://github.com').'/'.$c['repo'].(GitHubSync::provider($c)==='gitlab'?'/-/merge_requests/':'/pull/'),'~').'[1-9][0-9]*\z~D',$r['detail']))$detail='<a href="'.$detail.'" rel="noopener noreferrer">'.$detail.'</a>';$html.='<li>'.$e($r['at'].' · '.$r['actor'].' · '.$r['type']).' · '.$detail.'</li>';}$html.='</ul>';return $html;
    }
}
